// Whether atan2(y, x) is exactly representable: the NaN cases, and the results that are zeros.
fn atan2_exact(y: &Float, x: &Float) -> bool {
    y.atan2_prec_round_ref_ref(x, 1, Nearest).1 == Equal
}

#[allow(clippy::needless_pass_by_value)]
fn atan2_prec_round_properties_helper(y: Float, x: Float, prec: u64, rm: RoundingMode) {
    if rm == Exact && !atan2_exact(&y, &x) {
        assert_panic!(y.atan2_prec_round_ref_ref(&x, prec, Exact));
        return;
    }
    let (t, o) = y.clone().atan2_prec_round(x.clone(), prec, rm);
    assert!(t.is_valid());
    assert_rounding_ordering_consistent(&t, rm, o);

    let (t_alt, o_alt) = y.clone().atan2_prec_round_val_ref(&x, prec, rm);
    assert!(t_alt.is_valid());
    assert_eq!(ComparableFloatRef(&t_alt), ComparableFloatRef(&t));
    assert_eq!(o_alt, o);
    let (t_alt, o_alt) = y.atan2_prec_round_ref_val(x.clone(), prec, rm);
    assert!(t_alt.is_valid());
    assert_eq!(ComparableFloatRef(&t_alt), ComparableFloatRef(&t));
    assert_eq!(o_alt, o);
    let (t_alt, o_alt) = y.atan2_prec_round_ref_ref(&x, prec, rm);
    assert!(t_alt.is_valid());
    assert_eq!(ComparableFloatRef(&t_alt), ComparableFloatRef(&t));
    assert_eq!(o_alt, o);

    let mut t_alt = y.clone();
    let o_alt = t_alt.atan2_prec_round_assign(x.clone(), prec, rm);
    assert!(t_alt.is_valid());
    assert_eq!(ComparableFloatRef(&t_alt), ComparableFloatRef(&t));
    assert_eq!(o_alt, o);
    let mut t_alt = y.clone();
    let o_alt = t_alt.atan2_prec_round_assign_ref(&x, prec, rm);
    assert!(t_alt.is_valid());
    assert_eq!(ComparableFloatRef(&t_alt), ComparableFloatRef(&t));
    assert_eq!(o_alt, o);

    if let Ok(rug_rm) = rug_round_try_from_rounding_mode(rm) {
        let (rug_t, rug_o) = rug_atan2_prec_round(
            &rug::Float::exact_from(&y),
            &rug::Float::exact_from(&x),
            prec,
            rug_rm,
        );
        assert_eq!(
            ComparableFloatRef(&Float::from(&rug_t)),
            ComparableFloatRef(&t)
        );
        assert_eq!(rug_o, o, "y = {y} x = {x} prec = {prec} rm = {rm:?}");
    }

    // NaN exactly when an input is NaN
    assert_eq!(t.is_nan(), y.is_nan() || x.is_nan());
    if !t.is_nan() {
        // |atan2(y, x)| <= pi, so the result never overflows
        assert!(t.is_finite());
        assert!(PartialOrdAbs::le_abs(
            &t,
            &Float::from_unsigned_prec(4u32, 1).0
        ));
        if t.is_normal() {
            assert_eq!(t.get_prec(), Some(prec));
        }
        // atan2 is odd in y: the sign of y picks the half-plane
        let (t_neg, o_neg) = (-&y).atan2_prec_round_ref_ref(&x, prec, -rm);
        assert_eq!(ComparableFloatRef(&t_neg), ComparableFloatRef(&-&t));
        assert_eq!(o_neg, o.reverse());
    }

    if o == Equal {
        assert!(atan2_exact(&y, &x));
        for rm in exhaustive_rounding_modes() {
            let (t2, oo) = y.atan2_prec_round_ref_ref(&x, prec, rm);
            assert_eq!(ComparableFloatRef(&t2), ComparableFloatRef(&t));
            assert_eq!(oo, Equal);
        }
    } else {
        assert_panic!(y.atan2_prec_round_ref_ref(&x, prec, Exact));
    }
}

#[test]
fn atan2_prec_round_properties() {
    float_float_unsigned_rounding_mode_quadruple_gen_var_24().test_properties(
        |(y, x, prec, rm)| {
            atan2_prec_round_properties_helper(y, x, prec, rm);
        },
    );

    float_float_unsigned_rounding_mode_quadruple_gen_var_25().test_properties(
        |(y, x, prec, rm)| {
            atan2_prec_round_properties_helper(y, x, prec, rm);
        },
    );

    float_unsigned_rounding_mode_triple_gen_var_1().test_properties(|(y, prec, rm)| {
        // a NaN argument gives NaN, whatever the other one is
        let (t, o) = y.atan2_prec_round_ref_ref(&Float::NAN, prec, rm);
        assert!(t.is_nan());
        assert_eq!(o, Equal);
        let (t, o) = Float::NAN.atan2_prec_round_ref_ref(&y, prec, rm);
        assert!(t.is_nan());
        assert_eq!(o, Equal);
        if y.is_nan() {
            return;
        }
        // atan2(y, +infinity) is a zero with the sign of y, and atan2(+-0.0, x) for a
        // positive-signed x is too; both are exact
        for x in [Float::INFINITY, Float::ZERO] {
            if (x == 0u32 && y != 0u32) || (y.is_infinite() && x == Float::INFINITY) {
                continue;
            }
            let (t, o) = y.atan2_prec_round_ref_ref(&x, prec, rm);
            assert_eq!(
                ComparableFloat(t),
                ComparableFloat(if y.is_sign_negative() {
                    Float::NEGATIVE_ZERO
                } else {
                    Float::ZERO
                })
            );
            assert_eq!(o, Equal);
        }
    });
}

