// Whether MPFR can be asked about this input at all. Where |y/x| is extreme and the limiting turn
// fraction is itself a rounding boundary, `mpfr_atan2u` has to raise its working precision past
// |EXP(y) - EXP(x)|, which the exponent range allows to be about 2^31: one such case took MPFR 27
// minutes where this implementation takes 96 microseconds, and others do not finish at all. Those
// inputs are covered instead by `test_atan2_with_period_quadrant_boundary`, which sweeps the
// exponent gap across the threshold.
fn mpfr_is_usable(y: &Float, x: &Float, u: u64, prec: u64) -> bool {
    if u == 0
        || u > u64::from(u32::MAX)
        || !y.is_finite()
        || !x.is_finite()
        || *y == 0u32
        || *x == 0u32
    {
        return true;
    }
    let d = i64::from(y.get_exponent().unwrap()) - i64::from(x.get_exponent().unwrap());
    let p = i64::exact_from(prec);
    let nbits = u.significant_bits() - TrailingZeros::trailing_zeros(u);
    nbits > u64::exact_from(p + 1) || (d < p + 2 && d > -p - 1)
}

// Whether atan2u(y, x, u) is exactly representable at `prec`.
fn atan2_with_period_exact(y: &Float, x: &Float, u: u64, prec: u64) -> bool {
    y.atan2_with_period_prec_round_ref_ref(x, u, prec, Nearest)
        .1
        == Equal
}

#[allow(clippy::needless_pass_by_value)]
fn atan2_with_period_prec_round_properties_helper(
    y: Float,
    x: Float,
    u: u64,
    prec: u64,
    rm: RoundingMode,
) {
    if rm == Exact && !atan2_with_period_exact(&y, &x, u, prec) {
        assert_panic!(y.atan2_with_period_prec_round_ref_ref(&x, u, prec, Exact));
        return;
    }
    let (t, o) = y
        .clone()
        .atan2_with_period_prec_round(x.clone(), u, prec, rm);
    assert!(t.is_valid());
    assert_rounding_ordering_consistent(&t, rm, o);

    for (t_alt, o_alt) in [
        y.clone()
            .atan2_with_period_prec_round_val_ref(&x, u, prec, rm),
        y.atan2_with_period_prec_round_ref_val(x.clone(), u, prec, rm),
        y.atan2_with_period_prec_round_ref_ref(&x, u, prec, rm),
    ] {
        assert!(t_alt.is_valid());
        assert_eq!(ComparableFloatRef(&t_alt), ComparableFloatRef(&t));
        assert_eq!(o_alt, o);
    }
    let mut t_alt = y.clone();
    let o_alt = t_alt.atan2_with_period_prec_round_assign(x.clone(), u, prec, rm);
    assert_eq!(ComparableFloatRef(&t_alt), ComparableFloatRef(&t));
    assert_eq!(o_alt, o);
    let mut t_alt = y.clone();
    let o_alt = t_alt.atan2_with_period_prec_round_assign_ref(&x, u, prec, rm);
    assert_eq!(ComparableFloatRef(&t_alt), ComparableFloatRef(&t));
    assert_eq!(o_alt, o);

    // MPFR's atan2u agrees except at u = 0, where its own branches disagree with each other, and
    // except where it is too slow to ask
    if u != 0
        && u <= u64::from(u32::MAX)
        && mpfr_is_usable(&y, &x, u, prec)
        && let Ok(rug_rm) = rug_round_try_from_rounding_mode(rm)
    {
        let (rug_t, rug_o) = rug_atan2_with_period_prec_round(
            &rug::Float::exact_from(&y),
            &rug::Float::exact_from(&x),
            u,
            prec,
            rug_rm,
        );
        assert_eq!(
            ComparableFloatRef(&Float::from(&rug_t)),
            ComparableFloatRef(&t)
        );
        assert_eq!(
            rug_o, o,
            "y = {y} x = {x} u = {u} prec = {prec} rm = {rm:?}"
        );
    }

    // NaN exactly when an input is NaN
    assert_eq!(t.is_nan(), y.is_nan() || x.is_nan());
    if !t.is_nan() {
        // |atan2u(y, x, u)| <= u/2, so the result never overflows
        assert!(t.is_finite());
        assert!(PartialOrdAbs::le_abs(
            &t,
            &Float::from_unsigned_prec(u, prec + 2).0
        ));
        if t.is_normal() {
            assert_eq!(t.get_prec(), Some(prec));
        }
        // atan2u is odd with respect to y
        let (t_neg, o_neg) = (-&y).atan2_with_period_prec_round_ref_ref(&x, u, prec, -rm);
        assert_eq!(ComparableFloatRef(&t_neg), ComparableFloatRef(&-&t));
        assert_eq!(o_neg, o.reverse());
    }

    if o == Equal {
        assert!(atan2_with_period_exact(&y, &x, u, prec));
        for rm in exhaustive_rounding_modes() {
            let (t2, oo) = y.atan2_with_period_prec_round_ref_ref(&x, u, prec, rm);
            assert_eq!(ComparableFloatRef(&t2), ComparableFloatRef(&t));
            assert_eq!(oo, Equal);
        }
    } else {
        assert_panic!(y.atan2_with_period_prec_round_ref_ref(&x, u, prec, Exact));
    }
}

// There is no (Float, Float, u64, u64, RoundingMode) generator, so the period comes from the
// (Float, Float, u64, RoundingMode) one's precision: a power of two, whose quarter and half turns
// are representable; 2, which is atan2pi; a non-power of two; and the largest period there is.
// Choosing one per case rather than sweeping all of them keeps this test's cost in line with its
// siblings while still covering every period across the test population.
const PERIODS: [u64; 5] = [1, 2, 3, 360, u64::MAX];

fn period_for(prec: u64) -> u64 {
    PERIODS[usize::exact_from(prec % 5)]
}

#[test]
fn atan2_with_period_prec_round_properties() {
    float_float_unsigned_rounding_mode_quadruple_gen_var_24().test_properties(
        |(y, x, prec, rm)| {
            atan2_with_period_prec_round_properties_helper(y, x, period_for(prec), prec, rm);
        },
    );

    float_float_unsigned_rounding_mode_quadruple_gen_var_25().test_properties(
        |(y, x, prec, rm)| {
            atan2_with_period_prec_round_properties_helper(y, x, period_for(prec), prec, rm);
        },
    );
}

