// atan2_pi is atan2_with_period with a period of 2, so every variant must agree with it. The
// period-2 turn fractions are 1, 1/2, 1/4 and 3/4, all representable in two bits, so the special
// cases are exact at every precision except 3/4 at precision 1.
#[test]
fn atan2_pi_properties() {
    float_float_unsigned_rounding_mode_quadruple_gen_var_24().test_properties(
        |(y, x, prec, rm)| {
            let exact = y
                .atan2_with_period_prec_round_ref_ref(&x, 2, prec, Nearest)
                .1
                == Equal;
            if rm == Exact && !exact {
                assert_panic!(y.atan2_pi_prec_round_ref_ref(&x, prec, Exact));
                return;
            }
            let (t, o) = y.clone().atan2_pi_prec_round(x.clone(), prec, rm);
            assert!(t.is_valid());
            for (t_alt, o_alt) in [
                y.clone().atan2_pi_prec_round_val_ref(&x, prec, rm),
                y.atan2_pi_prec_round_ref_val(x.clone(), prec, rm),
                y.atan2_pi_prec_round_ref_ref(&x, prec, rm),
                y.atan2_with_period_prec_round_ref_ref(&x, 2, prec, rm),
            ] {
                assert_eq!(ComparableFloatRef(&t_alt), ComparableFloatRef(&t));
                assert_eq!(o_alt, o);
            }
            let mut t_alt = y.clone();
            let o_alt = t_alt.atan2_pi_prec_round_assign(x.clone(), prec, rm);
            assert_eq!(ComparableFloatRef(&t_alt), ComparableFloatRef(&t));
            assert_eq!(o_alt, o);
            let mut t_alt = y.clone();
            let o_alt = t_alt.atan2_pi_prec_round_assign_ref(&x, prec, rm);
            assert_eq!(ComparableFloatRef(&t_alt), ComparableFloatRef(&t));
            assert_eq!(o_alt, o);
            if rm == Nearest {
                for (t_alt, o_alt) in [
                    y.clone().atan2_pi_prec(x.clone(), prec),
                    y.clone().atan2_pi_prec_val_ref(&x, prec),
                    y.atan2_pi_prec_ref_val(x.clone(), prec),
                    y.atan2_pi_prec_ref_ref(&x, prec),
                ] {
                    assert_eq!(ComparableFloatRef(&t_alt), ComparableFloatRef(&t));
                    assert_eq!(o_alt, o);
                }
                let mut t_alt = y.clone();
                let o_alt = t_alt.atan2_pi_prec_assign(x.clone(), prec);
                assert_eq!(ComparableFloatRef(&t_alt), ComparableFloatRef(&t));
                assert_eq!(o_alt, o);
                let mut t_alt = y.clone();
                let o_alt = t_alt.atan2_pi_prec_assign_ref(&x, prec);
                assert_eq!(ComparableFloatRef(&t_alt), ComparableFloatRef(&t));
                assert_eq!(o_alt, o);
            }
        },
    );

    float_float_rounding_mode_triple_gen_var_43().test_properties(|(y, x, rm)| {
        let prec = max(y.significant_bits(), x.significant_bits());
        let exact = y
            .atan2_with_period_prec_round_ref_ref(&x, 2, prec, Nearest)
            .1
            == Equal;
        if rm == Exact && !exact {
            assert_panic!(y.atan2_pi_round_ref_ref(&x, Exact));
            return;
        }
        let (t, o) = y.clone().atan2_pi_round(x.clone(), rm);
        for (t_alt, o_alt) in [
            y.clone().atan2_pi_round_val_ref(&x, rm),
            y.atan2_pi_round_ref_val(x.clone(), rm),
            y.atan2_pi_round_ref_ref(&x, rm),
            y.atan2_with_period_round_ref_ref(&x, 2, rm),
        ] {
            assert_eq!(ComparableFloatRef(&t_alt), ComparableFloatRef(&t));
            assert_eq!(o_alt, o);
        }
        let mut t_alt = y.clone();
        let o_alt = t_alt.atan2_pi_round_assign(x.clone(), rm);
        assert_eq!(ComparableFloatRef(&t_alt), ComparableFloatRef(&t));
        assert_eq!(o_alt, o);
        let mut t_alt = y.clone();
        let o_alt = t_alt.atan2_pi_round_assign_ref(&x, rm);
        assert_eq!(ComparableFloatRef(&t_alt), ComparableFloatRef(&t));
        assert_eq!(o_alt, o);
    });

    rational_rational_unsigned_rounding_mode_quadruple_gen_var_4().test_properties(
        |(y, x, prec, rm)| {
            let exact = Float::atan2_with_period_rational_prec_round_ref(&y, &x, 2, prec, Nearest)
                .1
                == Equal;
            if rm == Exact && !exact {
                assert_panic!(Float::atan2_pi_rational_prec_round_ref(&y, &x, prec, Exact));
                return;
            }
            let (t, o) = Float::atan2_pi_rational_prec_round(y.clone(), x.clone(), prec, rm);
            assert!(t.is_valid());
            for (t_alt, o_alt) in [
                Float::atan2_pi_rational_prec_round_ref(&y, &x, prec, rm),
                Float::atan2_with_period_rational_prec_round_ref(&y, &x, 2, prec, rm),
            ] {
                assert_eq!(ComparableFloatRef(&t_alt), ComparableFloatRef(&t));
                assert_eq!(o_alt, o);
            }
            if rm == Nearest {
                for (t_alt, o_alt) in [
                    Float::atan2_pi_rational_prec(y.clone(), x.clone(), prec),
                    Float::atan2_pi_rational_prec_ref(&y, &x, prec),
                ] {
                    assert_eq!(ComparableFloatRef(&t_alt), ComparableFloatRef(&t));
                    assert_eq!(o_alt, o);
                }
            }
        },
    );
}

#[allow(clippy::type_repetition_in_bounds)]
fn primitive_float_atan2_pi_properties_helper<T: PrimitiveFloat>()
where
    Float: From<T> + PartialOrd<T>,
    Rational: ExactFrom<T>,
    for<'a> T: ExactFrom<&'a Float> + RoundingFrom<&'a Float>,
{
    primitive_float_pair_gen::<T>().test_properties(|(y, x)| {
        assert_eq!(
            NiceFloat(primitive_float_atan2_pi(y, x)),
            NiceFloat(primitive_float_atan2_with_period(y, x, 2))
        );
    });

    rational_pair_gen().test_properties(|(y, x)| {
        assert_eq!(
            NiceFloat(primitive_float_atan2_pi_rational::<T>(&y, &x)),
            NiceFloat(primitive_float_atan2_with_period_rational::<T>(&y, &x, 2))
        );
    });
}

#[test]
fn primitive_float_atan2_pi_properties() {
    apply_fn_to_primitive_floats!(primitive_float_atan2_pi_properties_helper);
}

#[test]
#[should_panic]
fn atan2_pi_prec_round_fail() {
    Float::ONE.atan2_pi_prec_round(Float::from(2.0f64), 0, Floor);
}

#[test]
#[should_panic]
fn atan2_pi_rational_prec_round_fail() {
    // 1/2 is not a quadrant diagonal, so no precision makes its angle exact
    Float::atan2_pi_rational_prec_round(Rational::ONE, Rational::TWO, 10, Exact);
}
